def atomic_json(path:Path,val:Any):
    path.parent.mkdir(parents=True,exist_ok=True); fd,tmp=tempfile.mkstemp(prefix=f".{path.name}.",dir=str(path.parent))
    try:
        with os.fdopen(fd,"w",encoding="utf-8") as f: json.dump(val,f,indent=2,sort_keys=True); f.write("\n"); f.flush(); os.fsync(f.fileno())
        os.replace(tmp,path)
    finally:
        if os.path.exists(tmp): os.unlink(tmp)
def sha(path):
    h=hashlib.sha256();
    with path.open("rb") as f:
        for c in iter(lambda:f.read(1<<20),b""): h.update(c)
    return h.hexdigest()
def read(path): return json.loads(path.read_text(encoding="utf-8"))
def cmd(s):
    try:return subprocess.check_output(s,shell=True,text=True,stderr=subprocess.STDOUT,timeout=20)
    except Exception as e:return f"command failed: {e}"

