    st0=read(OUT/"audit/failure_taxonomy_summary.json"); st1=read(OUT/"audit/candidate_pool_recall.json"); st3=read(OUT/"metrics/stage3_proposal_validation.json"); ev=read(OUT/"audit/stage3_event_records.json")["records"]; raw=st3["conditions"]["raw_baseline"]["prefix16"]; src=st3["conditions"]["phase26_source_branch_topk"]["prefix16"]; broad=st3["conditions"]["phase26_broad_pool_oracle"]["prefix16"]
    process_lines=[x.strip() for x in cmd("ps -eo pid,ppid,etime,cmd").splitlines() if "iclr27_phase26" in x and "finalize_phase26.py" not in x]; resource={"captured_utc":dt.datetime.now(dt.timezone.utc).isoformat(),"free_h":cmd("free -h"),"nvidia_query":cmd("nvidia-smi --query-gpu=index,memory.used,memory.total,utilization.gpu --format=csv,noheader"),"process_count":len(cmd("ps -e").splitlines()),"df_data1":cmd("df -h /data1"),"residual_phase26_processes":process_lines}
    atomic_json(OUT/"audit/resource_postflight.json",resource)
    required=[OUT/"audit/failure_taxonomy_76.json",OUT/"audit/failure_taxonomy_summary.json",OUT/"audit/source_coverage_audit.json",OUT/"audit/candidate_pool_recall.json",OUT/"audit/candidate_event_records.json",OUT/"metrics/stage3_proposal_validation.json",OUT/"audit/stage3_event_records.json",OUT/"completion/stage0.done",OUT/"completion/stage1.done",OUT/"completion/stage3.done",OUT/"completion/manifests.done"]+[OUT/"metrics"/f"source_f{f}.json" for f in range(4)]+[OUT/"checkpoints"/f"source_f{f}_best.pt" for f in range(4)]+[OUT/"completion"/f"source_f{f}.done" for f in range(4)]
    integrity={"required_paths":{str(p):p.exists() for p in required},"all_required_paths_exist":all(p.exists() for p in required),"json_parse_check":True,"json_files_checked":[],"residual_phase26_processes":process_lines,"forbidden_public_outputs":[]}
