    atomic_json(OUT/"audit/integrity.json",integrity)
    folds=[x["ceiling_correct"] for x in src["by_fold"]]; rawfold=[x["ceiling_correct"] for x in raw["by_fold"]]
    decision={"protocol":"trackocd_iclr27_phase26_proposal_source_candidate_coverage","execution_time":dt.datetime.now(dt.timezone.utc).isoformat(),"decision_code":"P26_GATE_P2_PASS_AUTHORIZE_CORRESPONDENCE","gate_p2":st3["gate_p2"],"frozen_phase24":{"raw":25,"pool_oracle":38,"setaware_top20":32},"frozen_phase25":{"attention_top27":30,"source":52,"target":47},"stage0":st0,"stage1":{"raw_prefix16":st1["prefix16"]["raw_ceiling"],"broad_pool_prefix16":st1["prefix16"]["broad_pool_ceiling"],"broad_transform_grid":st1["transform_extension"]},"stage2":{"architecture":"class-agnostic source head; eight bounded box candidates plus quality from aligned DINOv2 CLS/ROI and causal geometry","loss":"min positive box SmoothL1 + IoU-soft quality BCE + negative objectness penalty","steps":2000,"batch_size":64,"checkpoint_every":500,"amp":"bf16","folds":[]},"stage3":{"raw":raw,"source_branch":src,"broad_pool_oracle":broad,"source_folds":folds,"raw_folds":rawfold},"resources":{"launch_preflight":{"available_ram_gib":99,"total_ram_gib":125,"physical_gpus":[4,5,6,7],"data1_free_gib":20,"worker_count":4,"external_gpus_untouched":True},"postflight":str(OUT/"audit/resource_postflight.json"),"no_oom":True,"external_processes_touched":False},"incidents":[{"type":"duplicate_stage0","pids":[25464,26424],"action":"SIGTERM only PID25464; PID26424 exited naturally; diagnostic 27188/27189 terminated","artifact_hash_audit":str(OUT/"audit/duplicate_stage0_shutdown.json")},{"type":"stage1_raw_bug","root_cause":"raw comparison initially called fixed candidate helper","action":"minimal raw_only mode; reran Stage1; raw restored exactly 25/76"},{"type":"loader_slow_path","root_cause":"inherited helper rebuilt target set inside loop","action":"Phase26 efficient in-memory key alignment; source feature artifact unchanged"}],"public_q1":{"accessed":False,"sealed":True},"correspondence_authorized":True,"controller_threshold_state_frozen":True,"modern_backbone_download":False,"integrity":integrity}
